CREATE TABLE `prs` (
  `ticket_no` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `ticket_line_item` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `sku` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `p_org` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `p_group` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `pr_date` date DEFAULT NULL,
  `requestor_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `site_allocation` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ticket_type` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status_ticket` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `canvassing_no` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `canvassing_date` date DEFAULT NULL,
  `po_number` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `po_amount` decimal(15,2) DEFAULT NULL,
  `po_currency` varchar(5) COLLATE utf8mb4_unicode_ci DEFAULT 'IDR',
  `baseline_price` decimal(15,2) DEFAULT NULL,
  `baseline_currency` varchar(5) COLLATE utf8mb4_unicode_ci DEFAULT 'IDR',
  `vendor_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `qty` decimal(10,2) DEFAULT NULL,
  `uom` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `delivery_date` date DEFAULT NULL,
  `gr_date` date DEFAULT NULL,
  `item_description` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `assigned_pic` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `assigned_by_ai` tinyint(1) DEFAULT '0',
  `gp_officer` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `tr_date_gp` date DEFAULT NULL,
  `canvassing_date_approver_1` date DEFAULT NULL,
  `pillar` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`ticket_no`,`ticket_line_item`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
